def identity(p):
    s=p.lstat()
    assert stat.S_ISREG(s.st_mode) and not p.is_symlink()
    b=p.read_bytes()
    s2=p.lstat()
    assert (s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_mode)==(s2.st_dev,s2.st_ino,s2.st_size,s2.st_mtime_ns,s2.st_mode)
    return {"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest(),"git_blob":hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest(),"mode":format(stat.S_IMODE(s.st_mode),"04o"),"mtime_ns":str(s.st_mtime_ns)}
def census(base):
    rows={}
    for p in sorted(base.rglob("*")):
        assert not p.is_symlink()
        if p.is_dir(): continue
        rows[p.relative_to(base).as_posix()]=identity(p)
    return rows
before=census(root)
installed_before=census(target)
assert len(installed_before)==19 and sum(v["bytes"] for v in installed_before.values())==277107
assert installed_before["INSTALLATION.json"]["git_blob"]=="29533be91a1d5ee937de08f4990e3720627ff6a7"
disk=shutil.disk_usage(root).free
v=subprocess.run(["/usr/bin/vm_stat"],capture_output=True,text=True,check=True,timeout=10).stdout
page=int(re.search(r"page size of (\d+) bytes",v).group(1))
memory=sum(int(re.search(r"^"+re.escape(k)+r":\s+(\d+)\.",v,re.M).group(1)) for k in ("Pages free","Pages inactive","Pages speculative"))*page
owned=sum(x["bytes"] for x in before.values())+sum(x["bytes"] for x in installed_before.values())
additional=sum(x["bytes"] for x in payload)
assert disk>=256*1024*1024 and memory>=2*1024*1024*1024
assert owned+additional+65536<=2*1024*1024
out.mkdir(mode=0o700)
created={}
for f in payload:
    rel=PurePosixPath(f["path"])
    assert not rel.is_absolute() and ".." not in rel.parts
    p=out/str(rel)
    p.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
    b=f["content"].encode("utf-8")
    assert len(b)==f["bytes"] and hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()==f["git_blob"]
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,"wb") as w: w.write(b)
    created[f["path"]]=identity(p)
    assert created[f["path"]]["git_blob"]==f["git_blob"]
after=census(root)
installed_after=census(target)
assert installed_after==installed_before
assert all(after.get(k)==v for k,v in before.items())
